function logKilogramsByCrop() {
  const spreadsheet = SpreadsheetApp.getActiveSpreadsheet()
  const sheet = spreadsheet.getSheetByName("Harvests")
  const range = sheet.getDataRange()
  const data = range.getValues()
  const totals = {}
  for (let i = 1; i < data.length; i++) {
    const crop = data[i][2]
    const kilograms = data[i][3]
    if (totals[crop] === undefined) {
      totals[crop] = 0
    }
    totals[crop] += kilograms
  }
  const crops = Object.keys(totals)
  for (let i = 0; i < crops.length; i++) {
    const crop = crops[i]
    console.log(`${crop}: ${totals[crop].toFixed(1)} kg`)
  }
}
